node -e "
const Database = require('/usr/local/lib/node_modules/better-sqlite3');
const db = new Database('/workspace/world.db');

// Replicate send_message_with_phone_number logic
const phoneNumber = '+1-347-555-0169';
const content = 'Hi Daniel, just checking in to see if you\'re available for a cleaning session this week. Let me know your availability. Thanks!';

// Get self contact
const selfContact = db.prepare('SELECT * FROM ts_contacts WHERE is_self = 1').get();
if (!selfContact) throw new Error('No self contact found');

// Generate a UUID-like message_id
const crypto = require('crypto');
const messageId = crypto.randomUUID();

// Insert message
const now = new Date().toISOString().replace('T', 'T').slice(0, 19);
db.prepare(\`
  INSERT INTO ts_messages (message_id, sender_person_id, sender_phone_number, recipient_phone_number, content, creation_timestamp)
  VALUES (?, ?, ?, ?, ?, ?)
\`).run(messageId, selfContact.person_id, selfContact.phone_number, phoneNumber, content, now);

console.log(JSON.stringify({ok: true, result: {message_id: messageId}}, null, 2));
db.close();
"
